<?php
$root=dirname(__DIR__);$dist=$root.'/dist';$componentDir=$root.'/component';$packageDir=$root.'/package';$componentXml=simplexml_load_file($componentDir.'/decarocourses.xml');$packageXml=simplexml_load_file($packageDir.'/pkg_decarocourses.xml');if(!$componentXml||!$packageXml)exit(1);$version=trim((string)$componentXml->version);if($version!==trim((string)$packageXml->version))throw new RuntimeException('Version mismatch');@mkdir($dist,0775,true);function zipDir(string $source,string $target):void{$zip=new ZipArchive();if($zip->open($target,ZipArchive::CREATE|ZipArchive::OVERWRITE)!==true)throw new RuntimeException('Cannot create ZIP');$source=realpath($source);$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($source,FilesystemIterator::SKIP_DOTS));foreach($it as $f){if(!$f->isFile())continue;$path=$f->getRealPath();$local=str_replace(DIRECTORY_SEPARATOR,'/',substr($path,strlen($source)+1));$zip->addFile($path,$local);} $zip->close();}$component="$dist/com_decarocourses_$version.zip";$analytics="$dist/plg_xdecaroanalytics_decarocourses_$version.zip";$task="$dist/plg_task_decarocourses_$version.zip";zipDir($componentDir,$component);zipDir($root.'/plugins/xdecaroanalytics/decarocourses',$analytics);zipDir($root.'/plugins/task/decarocourses',$task);$stage=sys_get_temp_dir().'/pkg_decarocourses_'.bin2hex(random_bytes(4));mkdir($stage.'/packages',0775,true);copy($packageDir.'/pkg_decarocourses.xml',$stage.'/pkg_decarocourses.xml');copy($packageDir.'/script.php',$stage.'/script.php');copy($component,$stage."/packages/com_decarocourses_$version.zip");copy($analytics,$stage."/packages/plg_xdecaroanalytics_decarocourses_$version.zip");copy($task,$stage."/packages/plg_task_decarocourses_$version.zip");$package="$dist/pkg_decarocourses_$version.zip";zipDir($stage,$package);$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($stage,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::CHILD_FIRST);foreach($it as $f){$f->isDir()?rmdir($f->getPath